NS='http://www.sitemaps.org/schemas/sitemap/0.9';X='http://www.w3.org/1999/xhtml'
ET.register_namespace('',NS);ET.register_namespace('xhtml',X);root=ET.Element('{'+NS+'}urlset')
for p in sorted(ROOT.rglob('*.html')):
 if any(x.startswith(('_','.')) for x in p.relative_to(ROOT).parts):continue
 t=p.read_text();canon=re.search(r'<link\b[^>]*rel="canonical"[^>]*href="([^"]+)"',t)
 actual=DOMAIN+'/'+p.relative_to(ROOT).as_posix();actual=actual[:-10] if actual.endswith('index.html') else actual
 if not canon or canon[1]!=actual or re.search(r'<meta\b[^>]*name="robots"[^>]*content="[^"]*noindex',t):continue
 item=ET.SubElement(root,'{'+NS+'}url');ET.SubElement(item,'{'+NS+'}loc').text=actual
 for tag in re.findall(r'<link\b[^>]*rel="alternate"[^>]*>',t):
  a=re.search('hreflang="([^"]+)"',tag);b=re.search('href="([^"]+)"',tag)
  if a and b:ET.SubElement(item,'{'+X+'}link',{'rel':'alternate','hreflang':a[1],'href':b[1]})
ET.ElementTree(root).write(ROOT/'sitemap.xml',encoding='utf-8',xml_declaration=True)
